def build_matrix(k, row_conditions, col_conditions):
    def topo(conds):
        adj = defaultdict(list)
        for a, b in conds:
            adj[a].append(b)
        color, out = [0] * (k + 1), []

        def dfs(u):
            color[u] = 1
            for v in adj[u]:
                if color[v] == 1 or (color[v] == 0 and not dfs(v)):
                    return False
            color[u] = 2
            out.append(u)
            return True

        for u in range(1, k + 1):
            if color[u] == 0 and not dfs(u):
                return None
        return out[::-1]

    rows, cols = topo(row_conditions), topo(col_conditions)
    if rows is None or cols is None:
        return []
    r_of = {v: i for i, v in enumerate(rows)}
    c_of = {v: i for i, v in enumerate(cols)}
    M = [[0] * k for _ in range(k)]
    for v in range(1, k + 1):
        M[r_of[v]][c_of[v]] = v
    return M

def build_matrix(k, row_conditions, col_conditions):
    def topo(conds):
        adj, indeg = defaultdict(list), [0] * (k + 1)
        for a, b in conds:
            adj[a].append(b)
            indeg[b] += 1
        queue = deque(v for v in range(1, k + 1) if indeg[v] == 0)
        out = []
        while queue:
            u = queue.popleft()
            out.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    queue.append(v)
        return out if len(out) == k else None

    rows, cols = topo(row_conditions), topo(col_conditions)
    if rows is None or cols is None:
        return []
    r_of = {v: i for i, v in enumerate(rows)}
    c_of = {v: i for i, v in enumerate(cols)}
    M = [[0] * k for _ in range(k)]
    for v in range(1, k + 1):
        M[r_of[v]][c_of[v]] = v
    return M
